SELECT credit_limit_bucket, total_credit_limit FROM (SELECT CASE WHEN credit_limit >= 16900 THEN 'high' WHEN credit_limit >= 7100 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, SUM(credit_limit) AS total_credit_limit FROM customers WHERE signup_date > '2025-09-10' GROUP BY CASE WHEN credit_limit >= 16900 THEN 'high' WHEN credit_limit >= 7100 THEN 'mid' ELSE 'low' END) AS agg WHERE total_credit_limit < 44000;
